    if str(equipment.get("siteId", site_id)) != str(site_id):
        continue
    if str(equipment.get("status", "")).lower() not in {"operational", "active", "running"}:
        continue

    equipment_id = equipment.get("equipmentId") or equipment.get("id")
    if equipment_id is None:
        continue

    maintenance_response = session.post(
        f"{BASE_URL}/equipment/maintenance-schedule",
        json={
            "equipmentId": equipment_id,
            "siteId": site_id,
            "schedule": {
                "type": "preventive",
                "date": "Specify maintenance date",
            },
        },
    )
    maintenance_response.raise_for_status()

report_response = session.post(
    f"{BASE_URL}/reports/generate",
    json={
        "siteId": site_id,
        "include": [
            "regulatory updates",
            "current operational status of machinery",
        ],
        "customSections": [
            "regulatory updates",
            "current operational status of machinery",
        ],
    },
)
report_response.raise_for_status()

