inventory_response = session.get(f"{BASE_URL}/inventory/status")
inventory_response.raise_for_status()
inventory_data = inventory_response.json()

project_material_ids = {
    str(material.get("materialId") or material.get("id"))
    for material in project_materials_data.get("materials", [])
    if material.get("materialId") is not None or material.get("id") is not None
}

