import os
import requests

BASE_URL = os.getenv("SOCBENCH_BASE_URL", "https://api.socbench.example").rstrip("/")
session = requests.Session()
session.headers.update({"Accept": "application/json"})

# Trigger the hook that enables automatic threat alerts.
hook_id = os.getenv("SOCBENCH_HOOK_ID", "automatic-threat-alerts")
hook_response = session.post(
    f"{BASE_URL}/trigger-hook",
    json={"hook_id": hook_id},
    timeout=30,
)
hook_response.raise_for_status()

# Retrieve threats and software inventory to identify possible vulnerability associations.
threats_response = session.get(f"{BASE_URL}/threats", timeout=30)
threats_response.raise_for_status()
threats_data = threats_response.json()
threats = threats_data if isinstance(threats_data, list) else threats_data.get("threats", [])

software_response = session.get(f"{BASE_URL}/software", timeout=30)
software_response.raise_for_status()
software_data = software_response.json()
software = software_data if isinstance(software_data, list) else software_data.get("software", [])

# Match software records to threats using any shared identifiers or names.
def searchable_values(record):
    if not isinstance(record, dict):
        return set()
    return {
        str(value).casefold()
        for key, value in record.items()
        if value is not None and isinstance(value, (str, int, float))
    }

software_by_value = {}
for item in software:
    for value in searchable_values(item):
        software_by_value.setdefault(value, []).append(item)

threat_software_associations = []
for threat in threats:
    threat_values = searchable_values(threat)
    matches = []
    seen = set()
    for value in threat_values:
        for item in software_by_value.get(value, []):
            marker = repr(item)
            if marker not in seen:
                seen.add(marker)
                matches.append(item)
    threat_software_associations.append(
        {"threat": threat, "associated_software": matches}
    )

# Update or remove alert rules according to the current threat conditions.
alerts_response = session.get(f"{BASE_URL}/alerts", timeout=30)
alerts_response.raise_for_status()
alerts_data = alerts_response.json()
alerts = alerts_data if isinstance(alerts_data, list) else alerts_data.get("alerts", [])

threat_conditions = [
    {
        "threat_id": threat.get("id"),
        "severity": threat.get("severity"),
        "type": threat.get("type", threat.get("name")),
        "associated_software": association["associated_software"],
    }
    for threat, association in zip(threats, threat_software_associations)
    if isinstance(threat, dict)
]

for alert in alerts:
    if not isinstance(alert, dict) or alert.get("id") is None:
        continue

    alert_id = alert["id"]
    if threat_conditions:
        updated_alert = dict(alert)
        updated_alert["conditions"] = threat_conditions
        updated_alert["enabled"] = True
        response = session.put(
            f"{BASE_URL}/alerts/{alert_id}",
            json=updated_alert,
            timeout=30,
        )
        response.raise_for_status()
    else:
        response = session.delete(
            f"{BASE_URL}/alerts/{alert_id}",
            timeout=30,
        )
        response.raise_for_status()

# Generate compliance reports after updating alert rules and reviewing software associations.
compliance_response = session.get(f"{BASE_URL}/compliance/reports", timeout=30)
compliance_response.raise_for_status()
compliance_reports = compliance_response.json()

report_response = session.post(f"{BASE_URL}/reports/generate", json={}, timeout=30)
report_response.raise_for_status()

